TEXTS.update({
 "nav.sources": "Sources & scientific basis", "farm.edit": "Edit this farm",
 "sci.help": "How is this calculated?", "sci.basis.title": "How is this calculated? Scientific basis and limits",
 "sci.section.data": "What data it uses", "sci.section.how": "How it is calculated", "sci.section.meaning": "What it means", "sci.section.limits": "Limits",
 "sci.types": "Type of data involved", "sci.more": "Full sources and scientific status", "sci.types.title": "Types of data in NovaScope",
 "sci.kind.observation": "Observation", "sci.kind.estimate": "Estimate", "sci.kind.forecast": "Forecast", "sci.kind.model": "Model", "sci.kind.user": "Farmer data",
 "sci.kind.observation.desc": "A value measured directly by an instrument (satellite sensor, weather station). This version does not show direct observations: satellite soil moisture (SMAP) and vegetation (NDVI) are not integrated yet.",
 "sci.kind.estimate.desc": "A value derived from satellite observations and reanalysis on a grid, such as NASA POWER (cells of ~50 km). It is not a measurement inside your field. Indicators computed from it (SPI, 30-day rain ratio) are also estimates.",
 "sci.kind.forecast.desc": "Output of weather models about the coming days (Open-Meteo, not NASA). It can change when the models update.",
 "sci.kind.model.desc": "A calculation made by NovaScope under explicit assumptions: suitability index, compatibility, rotation score, evaporative demand (Hargreaves). It is only as reliable as its inputs and assumptions.",
 "sci.kind.user.desc": "Information you typed in: crop, irrigation, soil pH, history, water availability. It is shown as farmer data and is not checked as a measurement.",
 "sci.rec.short": "Compatibility compares each crop's needs with the area's historical climate. It is a guide, not a prediction.",
 "sci.rec.data": "- Historical daily climate from NASA POWER (estimate, ~50 km cells, about 15 years by default).\n- Crop requirements from the project's crop catalogue: general approximations in the style of FAO EcoCrop / CropWat, not yet validated with INIFAP.\n- Your farm details: irrigation, soil pH, previous crops (farmer data).",
 "sci.rec.how": "For each historical year the app simulates one crop cycle from the typical sowing month and scores (0–1) how well the daily mean temperature fits the crop's temperature range (T) and, if rainfed, how much of the crop's average water need the effective rain would cover (W; effective rain = 75 % of rainfall). With irrigation, enough water is assumed (W = 1). The index is the average over the years of √(T × W).",
 "sci.rec.meaning": "High ≥ 0.70 · Moderate ≥ 0.45 · Low < 0.45. These cut-offs are heuristic and have not been calibrated against real yields. “Insufficient information” means the crop could not be evaluated (perennial, missing parameters, no documented sowing window or too few years).",
 "sci.rec.limits": "- It is not a probability of success or a yield forecast.\n- Crop parameters and thresholds are unvalidated approximations (every catalogue entry is marked as not verified), so this is not scientifically validated advice.\n- Climate cells are ~50 km wide and no soil is measured. Soil pH out of range, a repeated botanical family and the unvalidated catalogue appear as limitations but do not change the score.\n- Pests, markets, frost timing inside the cycle and farm management are not considered. It does not replace an agronomist or INIFAP guidance.",
 "sci.rec.item": "Score {idx} = average over {n} historical years of √(temperature fit × water coverage). It is a model result built from NASA POWER estimates{farmer}.",
 "sci.rec.item.farmer": " and the details you entered", "sci.rec.item.unverified": "Catalogue status: crop parameters not validated with INIFAP/FAO. Treat the category as orientation only.",
 "sci.rec.item.verified": "Catalogue status: marked as verified in the catalogue file.",
 "sci.rot.short": "Rotation scores combine five criteria with weights chosen by judgement. They compare options; they do not forecast yields.",
 "sci.rot.data": "- The same historical NASA POWER climate (estimate) and crop catalogue used in the recommendations.\n- Your current crop, excluded crops and previous cycles (farmer data).\n- Weights you can adjust. The initial weights are a judgement, not derived from data.",
 "sci.rot.how": "The app tests every valid sequence of 3–5 years. Hard rules: no botanical family repeated in consecutive cycles, and the first crop must not repeat the family of your current crop. Each sequence receives 0–1 scores for climate suitability, water, soil cover (a qualitative class from the catalogue), relative potential (the suitability index used as an approximation, not yield) and lower climate risk (1 − historical failure rate). Initial weights: climate 0.25, water 0.25, soil cover 0.15, potential 0.15, risk 0.20 (editable in data/reference/rotation_weights.json). A +0.03 bonus is added for a transition to a legume (a potential benefit, not measured).",
 "sci.rot.meaning": "The score (0–1) ranks sequences under your weights; it is not a probability. The robustness test repeats the ranking with equal weights and with 60 % emphasis on each criterion, and reports in what share of those variations the best sequence stays first.",
 "sci.rot.limits": "- Historical climate is a reference, not a forecast of the coming years.\n- Weights, catalogue values and the legume bonus are unvalidated and pending calibration with agricultural advisers.\n- Fixed nitrogen, soil health, pests, prices and farm constraints are not modelled.\n- Where a crop has too few years for an empirical probability, risk uses the suitability index as an approximation.",
 "sci.alerts.short": "Alerts mix a 7-day weather forecast with estimates from NASA POWER history. Colours follow operational thresholds, not crop-specific physiology.",
 "sci.alerts.data": "- Forecast (Open-Meteo, weather models, not NASA): maximum and minimum temperature, rain and wind.\n- Estimate (NASA POWER): 3-month SPI, the 30-day ratio of rain to evaporative demand (demand estimated with the Hargreaves method) and the 90th percentile of maximum temperature for each month.\n- Crop parameters from the catalogue: heat and frost sensitivity and maximum growth temperature.",
 "sci.alerts.how": "Each of the 8 risks compares a value with thresholds. Examples: SPI-3 ≤ −1.0 yellow and ≤ −1.5 red; rain ≥ 25 mm/day yellow and ≥ 50 mm red; wind ≥ 40 km/h yellow and ≥ 60 red; rain ÷ evaporative demand < 0.7 yellow and < 0.4 red (rainfed only); a heat wave is 3 or more consecutive days above the month's historical 90th percentile (5 or more is red). Frost thresholds depend on the crop's frost sensitivity. The overall risk is the worst individual risk.",
 "sci.alerts.meaning": "Green: no relevant risk with the available data. Yellow: caution. Red: high risk. Gray: not enough information, which does not mean there is no risk. Each alert is labelled as forecast or estimate.",
 "sci.alerts.limits": "- Thresholds are generic operational values, configurable and not validated species by species.\n- Forecasts can change. The flood indicator uses rainfall only (no terrain or streams). NASA POWER cells are ~50 km wide.\n- Water stress is not evaluated for irrigated farms.\n- Alerts do not replace local advice or your own observation of the field.",
 "sci.water.short": "A visual guide to recent rainfall compared with normal. It is not a measured water percentage.",
 "sci.water.data": "- Daily rain and temperature from NASA POWER (estimate, ~50 km cells).\n- The 3-month SPI drought index, computed from the same data (estimate).\n- Whether the farm is irrigated (farmer data).",
 "sci.water.how": "Ratio = rain over the last 30 days ÷ average rain over the same calendar period in earlier years (at least 10 years are needed). Favourable: ratio ≥ 0.8 and SPI-3 ≥ −0.5. Possible stress: ratio < 0.5 or SPI-3 ≤ −1 (shown as “limited” on irrigated farms). Anything in between is limited. If the period is normally very dry (average < 10 mm) the result is limited with a note, and with fewer than 10 years of history the information is insufficient.",
 "sci.water.meaning": "The tank is an illustration of the category. Its fill level is not a measured percentage of soil or reservoir water.",
 "sci.water.limits": "- There is no soil moisture: satellite soil moisture (SMAP) is not integrated.\n- It does not compute irrigation needs, and with irrigation rain is not the only source of water.\n- Rain comes from ~50 km cells and can differ from your field.",
 "sci.env.short": "Forecast cards and charts combine weather-model forecasts with NASA POWER estimates. They are context, not measurements in your field.",
 "sci.env.data": "- 7-day outlook: Open-Meteo forecast (weather models).\n- Rain, temperature and solar radiation history and anomalies: NASA POWER (estimate).\n- SPI-3: estimate computed from POWER monthly rain.",
 "sci.env.how": "Forecast cards are coloured with simple rules on daily values (for example maximum ≥ 40 °C, minimum ≤ 0 °C, rain ≥ 25 mm or wind ≥ 60 km/h turn red). Anomalies compare each month with the average of the same month over the available years. SPI-3 compares the last 3 months of rain with normal after fitting a gamma distribution (McKee et al., 1993).",
 "sci.env.meaning": "Icons and colours are a visual guide, not a crop-specific warning. For crop-specific alerts see Alerts in Overview.",
 "sci.env.limits": "- Vegetation (NDVI) and soil moisture (SMAP) are not integrated, so they are not shown.\n- SPI needs about 20 years of data for a reliable reading; shorter series carry a warning.\n- POWER cells (~50 km) are not a measurement inside your field.",
 "sources.title": "Sources & scientific basis", "sources.back": "Back to Overview",
 "sources.intro": "Everything NovaScope shows comes from the sources below. Only sources the app actually uses are listed, and links open the official pages in a new tab.",
 "sources.status.title": "Scientific status of this version",
 "sources.status.body": "- Climate data are estimates and forecasts, not measurements inside your field.\n- The crop catalogue and its thresholds are approximations that have not been validated with INIFAP or FAO (every crop is marked as not verified).\n- Alert thresholds, compatibility cut-offs (0.70 and 0.45) and rotation weights are heuristic and configurable; they have not been calibrated against yields.\n- Indicators are orientation. They are not guaranteed predictions and do not replace agronomic advice.\n- This version covers Chihuahua, Mexico only.",
 "sources.used.title": "Data sources used by the app", "sources.methods.title": "Methods and references behind the calculations",
 "sources.methods.note": "These are methods the code implements or references. They are not data sources.",
 "sources.notint.title": "Not integrated in this version",
 "sources.notint.body": "These are not used and no result depends on them: satellite soil moisture (SMAP), direct GPM IMERG, vegetation indices (NDVI from Sentinel-2/HLS), ECOSTRESS, ERA5 and soil data for Mexico.",
 "sources.attr.title": "Attribution",
 "sources.attr.body": "- Climate history: NASA POWER (cite NASA/POWER).\n- Weather forecasts: [Weather data by Open-Meteo.com](https://open-meteo.com/) (CC BY 4.0).\n- Map: © OpenStreetMap contributors.",
 "sources.l.provides": "What it provides", "sources.l.use": "How NovaScope uses it", "sources.l.limits": "Limitations", "sources.l.license": "License / attribution", "sources.l.links": "Official pages",
 "lnk.home": "Official site", "lnk.docs": "Documentation", "lnk.daily": "Daily API docs", "lnk.cite": "How to cite", "lnk.license": "License", "lnk.terms": "Terms of use",
 "lnk.copyright": "Copyright and license", "lnk.spi": "SPI overview and citation", "lnk.doi": "Original paper (DOI)", "lnk.ecocrop": "FAO EcoCrop", "lnk.cropwat": "FAO CropWat",
 "src.power.name": "NASA POWER (Prediction Of Worldwide Energy Resources)",
 "src.power.provides": "Daily meteorological and solar parameters since 1981 on a global grid, delivered by the POWER API (agroclimatology community). NovaScope requests mean, maximum and minimum temperature at 2 m, corrected precipitation, surface solar radiation, relative humidity and wind at 2 m.",
 "src.power.use": "The historical climate of the farm's location (about 15 years by default, up to roughly 5 days before today) feeds crop suitability, rotation, the SPI-3 drought index, the water summary, anomalies and the environmental charts. Results are stored locally and flagged when a stored copy is shown.",
 "src.power.limits": "Values are estimates built from satellite observations and reanalysis (MERRA-2 for temperature; precipitation corrected with IMERG, according to the project's documentation) on cells of about 0.5° × 0.625° (~50 km). They are not measurements inside a field, and recent days can be missing because of delivery delay.",
 "src.power.license": "Open data. Cite NASA/POWER when using it.",
 "src.openmeteo.name": "Open-Meteo Forecast API",
 "src.openmeteo.provides": "Daily weather-model forecasts for the next 7 days: maximum and minimum temperature, precipitation (total and maximum probability), maximum wind speed and gusts at 10 m, and shortwave radiation. Open-Meteo combines open data from national weather services.",
 "src.openmeteo.use": "The 7-day outlook cards and the short-term alerts (extreme temperature, frost, heat wave, heavy rain, flood indicator, strong wind). Responses are stored for a few hours.",
 "src.openmeteo.limits": "It is a forecast, not NASA data, and it can change when the models update. The free API is for non-commercial use; commercial use requires contacting Open-Meteo.",
 "src.openmeteo.license": "CC BY 4.0: display “Weather data by Open-Meteo.com” with a link.",
 "src.osm.name": "OpenStreetMap (map tiles)",
 "src.osm.provides": "The base map shown behind farm locations and boundaries.",
 "src.osm.use": "Overview map and the farm location picker, drawn with Folium. It is not used in any calculation.",
 "src.osm.limits": "Cartographic background only; it holds no agronomic information. Field boundaries you draw are farmer data.",
 "src.osm.license": "© OpenStreetMap contributors.",
 "src.spi.name": "Standardized Precipitation Index (SPI-3) · McKee, Doesken and Kleist (1993)",
 "src.spi.use": "A gamma distribution is fitted to 3-month rainfall from NASA POWER for each calendar month. The result drives the meteorological drought alert and the water summary.",
 "src.spi.limits": "A reliable reading needs about 20 years of data (shorter series show a warning). The index assumes a distribution that may not fit every environment.",
 "src.hargreaves.name": "Hargreaves–Samani reference evapotranspiration (ET0) · Hargreaves and Samani (1985)",
 "src.hargreaves.use": "Estimates atmospheric water demand from temperature and latitude, for the 30-day water-stress alert (rain ÷ ET0).",
 "src.hargreaves.limits": "A simplified method that needs only temperature and latitude. It is an estimate of demand, not a measurement of what your crop uses.",
 "src.fao.name": "FAO crop references (EcoCrop and CropWat)",
 "src.fao.use": "The catalogue (data/crops/crops.json) holds general approximate values for temperature range, cycle length and water need, in the style of FAO EcoCrop and CropWat tables. The links point to the official FAO tools as the reference for this kind of parameter.",
 "src.fao.limits": "The catalogue values are approximations and have not been validated with INIFAP or FAO (every crop is marked verified = false). FAO reports that EcoCrop was discontinued around 2015 and is now accessible through its GAEZ platform.",
})
